import { Routes, Route } from "react-router-dom";
import StartQuiz from "./component/StartQuiz";
import { useState } from "react";
// import Quiz from "./component/Quiz";



function App() {
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");
    const quizList = async () => {
        try {
        setLoading(true);
        setError("");
        const res = await fetch("/quizList.json", { cache: "no-store" });
        if (!res.ok)
            throw new Error(
            `Nie udało się pobrać quizList.json (HTTP ${res.status}).`
            );
        const data = await res.json();

        // Prosta walidacja struktury
        if (!Array.isArray(data))
            throw new Error("Plik JSON musi zawierać tablicę quizów.");
        data.forEach((q, i) => {
            if (typeof q.q !== "string")
            throw new Error(`Pytanie #${i + 1}: brak pola 'question' (string).`);
            if (!Array.isArray(q.options) || q.options.length !== 4)
            throw new Error(
                `Pytanie #${i + 1}: 'options' musi mieć 4 odpowiedzi.`
            );
            if (
            typeof q.correctAnswer !== "number" ||
            q.correctAnswer < 0 ||
            q.correctAnswer > 3
            )
            throw new Error(
                `Pytanie #${i + 1}: 'correctAnswer' musi być liczbą 0–3.`
            );
        });

        setQuestions(data);
        setCurrent(0);
        setScore(0);
        setFinished(false);
        } catch (e) {
        setError(e.message || "Nieznany błąd podczas wczytywania pytań.");
        } finally {
        setLoading(false);
        }
    };
  return (
    <Routes>
      <Route path="/" element={<StartQuiz listQuiz={quizzes} />} />
      {/* <Route path="/quiz/:id" element={<Quiz quizzes={quizzes} />} /> */}
    </Routes>
  );
}

export default App;
